import { test, expect } from '@playwright/test';

test.describe('File Upload Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/upload');
  });

  test('should successfully upload a file and display confirmation', async ({ page }) => {
    // Setup: intercept the file upload API endpoint
    await page.route('**/upload', (route) => {
      route.continue();
    });

    // Setup: intercept the file upload response
    await page.route('**/upload', (route) => {
      route.abort('blockedbyclient');
    });

    // Setup: intercept the file upload response with success status
    await page.route('**/upload', (route) => {
      route.continue({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({
          success: true,
          message: 'File uploaded successfully',
          filename: 'test-document.pdf',
          size: 10240
        }),
      });
    });

    // Action: select a file using getByLabel
    const fileInput = page.getByLabel('Choose file');
    await fileInput.setInputFiles('test-document.pdf');

    // Action: click the submit button using getByRole
    const submitButton = page.getByRole('button', { name: /upload/i });
    await submitButton.click();

    // Wait for navigation and confirmation
    await page.waitForURL('**/upload/success');

    // Assertion: verify success heading is displayed
    const successHeading = page.getByRole('heading', { name: /file uploaded/i });
    await expect(successHeading).toBeVisible();

    // Assertion: verify uploaded file name is displayed
    const uploadedFileName = page.getByText('test-document.pdf');
    await expect(uploadedFileName).toBeVisible();

    // Assertion: verify success message is present
    const successMessage = page.getByText('File uploaded successfully');
    await expect(successMessage).toBeVisible();
  });

  test('should handle file upload failure and display error message', async ({ page }) => {
    // Setup: intercept the file upload API endpoint
    await page.route('**/upload', (route) => {
      route.abort('blockedbyclient');
    });

    // Setup: intercept the file upload response with error status
    await page.route('**/upload', (route) => {
      route.continue({
        status: 500,
        contentType: 'application/json',
        body: JSON.stringify({
          success: false,
          message: 'Server error during upload',
          error: 'Internal server error'
        }),
      });
    });

    // Action: select a file using getByLabel
    const fileInput = page.getByLabel('Choose file');
    await fileInput.setInputFiles('large-file.zip');

    // Action: click the submit button using getByRole
    const submitButton = page.getByRole('button', { name: /upload/i });
    await submitButton.click();

    // Wait for error state
    await page.waitForTimeout(500);

    // Assertion: verify error heading is displayed
    const errorHeading = page.getByRole('heading', { name: /file upload failed/i });
    await expect(errorHeading).toBeVisible();

    // Assertion: verify error message is displayed
    const errorMessage = page.getByText('Server error during upload');
    await expect(errorMessage).toBeVisible();

    // Assertion: verify success heading is NOT visible
    const successHeading = page.getByRole('heading', { name: /file uploaded/i });
    await expect(successHeading).not.toBeVisible();
  });
});
